16	  const types = countDistinctMonsterTypes(otherCards);
17	  return (
18	    BASE_POINTS +
19	    (types > THREE_TYPES
20	      ? POINTS_PER_TYPE_BEYOND_THREE * (types - THREE_TYPES)
21	      : POINTS_WITHIN_THREE_TYPES)
22	  );
23	};
