// current semantics vs proposed equivalence, brute-forced over random armies
const T = ["sphinx","chimera","orthrus","zombie","hydra","cyclops","undead-warrior"];
const distinct = cs => new Set(cs.map(c=>c.monster)).size;
const pts = n => 1 + (n>3 ? 2*(n-3) : 1);
const current = army => army.reduce((s,c,i)=> c.monster==="sphinx" ? s+pts(distinct(army.filter((_,o)=>o!==i))) : s, 0);
const proposed = army => {
  const sphinxCount = army.filter(c=>c.monster==="sphinx").length;
  if (sphinxCount === 0) return 0;
  const all = distinct(army);
  const seen = sphinxCount === 1 ? all - 1 : all;
  return sphinxCount * pts(seen);
};
let bad=0;
for (let t=0;t<200000;t++){
  const n = Math.floor(Math.random()*8);
  const army = Array.from({length:n},()=>({monster:T[Math.floor(Math.random()*T.length)]}));
  if (current(army)!==proposed(army)) { if(bad++<5) console.log("MISMATCH",JSON.stringify(army),current(army),proposed(army)); }
}
console.log(bad===0 ? "EQUIVALENT on 200k random armies" : `${bad} mismatches`);
